	(5530440, 'Surprising 8-Slot Expander Box Coupon', '', 'Use this voucher to get one Surprising 8-Slot Expander Box, which gives you a coupon to increase the capacity of your Equip, Use, Set-up, or Etc inventory tab. The gift box will be available for use until TKTKTK.  ', 100, '-1.0', -1, 0, 0, 0, 0, 0, 0, 0, '', '', 100, '', 0, '', 0, ''),
	(5530441, 'Surprising Growth Crystal Coupon', '', 'Use this voucher to get a small crystal that immediately grants you a random amount of extra EXP. \\n#cThe Mysterious Growth Blessing item acquired through the coupon can be used until TKTKTK and level capped users will not see any effects.#', 100, '-1.0', -1, 0, 0, 0, 0, 0, 0, 0, '', '', 100, '', 0, '', 0, ''),
	(5530442, 'Premium Scroll for Pet Equip for Weapon ATT 100%', '', 'Adds Weapon ATT to pet equipment, premium-style. \\r\\n#cSuccess rate: 100%#, #cWeapon ATT +4 to +5#. \\r\\n#cDouble-click the scroll in your Cash tab to move it to your Use tab.# \\r\\n#cCannot be used with a Lucky Day Scroll.#', 100, '-1.0', -1, 0, 0, 0, 0, 0, 0, 0, '', '', 100, '', 0, '', 0, ''),
	(5530443, 'Premium Scroll for Pet Equip for Magic ATT 100%', '', 'Adds Magic ATT to pet equipment, premium-style. \\r\\n#cSuccess rate: 100%#, #cMagic ATT +4 to +5#. \\r\\n#cDouble-click the scroll in your Cash tab to move it to your Use tab.# \\r\\n#cCannot be used with a Lucky Day Scroll.#', 100, '-1.0', -1, 0, 0, 0, 0, 0, 0, 0, '', '', 100, '', 0, '', 0, ''),
	(5530444, 'Sweet Sugar Chair Coupon', '', '#cDouble-click# to receive the Sweet Sugar Chair, and about a hundred cavities. Recovers 100 HP and MP every 10 seconds.\\n#cThis chair moves with the sitter due to its bottom-hugging construction.#', 100, '-1.0', -1, 0, 0, 0, 0, 0, 0, 0, '', '', 100, '', 0, '', 0, ''),
