	(2920000, 'Lv. 5 Armor Bypass Key', '', 'Drag the #cBypass Key# into an equip window slot (#chotkey E#) to equip armors that are for #cup to 5 levels# above yours for #c3 days#. \\n#cYou may not stack# #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill may not use Bypass Keys. \\n#c Available slots: Cap, shoulder accessory, clothes, pants, outfit, mantle, gloves, belt, shoes# ', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(2920001, 'Lv. 5 Weapon Bypass Key', '', 'Drag the #cBypass Key# into an equip window slot (#chotkey E#) to equip weapons that are for #cup to 5 levels# above yours for #c3 days#. \\n#cYou may not stack# #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill may not use Bypass Keys. Can only be used on equipment.\\n#c Available slots: Weapon, shield, secondary weapon#', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(2920002, 'Lv. 5 Accessory Bypass Key', '', 'Drag the #cBypass Key# into an equip window slot (#chotkey E#) to equip accessories that are for #cup to 5 levels# above yours for #c3 days#. \\n#cYou may not stack# #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill may not use Bypass Keys. \\n#c Available slots: Pendant, ring, eye accessory, face, earrings, pocket#', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(2920003, 'Lv. 5 ETC Bypass Key', '', 'Drag the #cBypass Key# into an equip window slot (#chotkey E#) to equip ETC equipment that are for #cup to 5 levels# above yours for #c3 days#. \\n#cYou may not stack# #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill may not use Bypass Keys. \\n#c Available slots: Medal, badge, dragon, Mechanic equipment#', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(2920004, 'Lv. 20 Armor Bypass Key', '', 'Drag the #cBypass Key# into an Equip window slot (#chotkey E#) to equip armors that are #c20 levels# higher than yours for #c3 days#. \\nYou cannot stack and use #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill cannot use Bypass Keys. \\n#c Available slots: Cap, shoulder accessory, tops, bottoms, outfits, capes, gloves, belt, shoes# ', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(2920005, 'Lv. 20 Weapon Bypass Key', '', 'Drag the #cBypass Key# into the Equip window slot (#chotkey E#) to equip weapons that are for #c20 levels# higher than yours for #c3 days#. \\nYou cannot stack and use #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill cannot use Bypass Keys. Unable to use on the items that cannot be equipped/removed.\\n#c Available slots: Weapon, shield, secondary weapon#', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(2920006, 'Lv. 20 Accessory Bypass Key', '', 'Drag the #cBypass Key# into the Equip window slot (#chotkey E#) to equip accessories that are for #c20 levels# higher than yours for #c3 days#. \\nYou cannot stack and use #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill cannot use Bypass Keys. \\n#c Available slots: Pendant, ring, eye accessory, face accessory, earrings, pocket#', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(2920007, 'Lv. 20 ETC Bypass Key', '', 'Drag the #cBypass Key# into the Equip window slot (#chotkey E#) to equip ETC equipments that are #c20 levels# higher than yours for #c3 days#. \\nYou cannot stack and use #cBypass Keys of other levels#. Characters with the #cEmpress\'s Might# skill cannot use Bypass Keys. \\n#c Available slots: Medal, badge, dragon, Mechanic equipment#', 100, '-1.0', -1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
