	(4033293, 'Brazen Bravery', '', 'One of the key elements of becoming a Mesoranger. You\'ll stand up to almost anyone.', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(4033294, 'Bountiful Bravery', '', 'One of the key elements of becoming a Mesoranger. Nothing dares face you!', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(4033295, 'Will', '', 'One of the key elements of becoming a Mesoranger. Still a little wishy-washy.', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(4033296, 'Willful Will', '', 'One of the key elements of becoming a Mesoranger. Your heart\'s in the right place.', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(4033297, 'Unwavering Will', '', 'One of the key elements of becoming a Mesoranger. Nothing gets in your way!', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(4033298, 'Trust', '', 'One of the key elements of becoming a Mesoranger. You are unstoppable once your sights are set!', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
