	(3994184, 'Cassandra\'s Strange Potion ', '', 'Hold onto this for 30 minutes and the cold weather will turn it into slush. It\'s so delicate it will disappear if you log out.', 1, '1.0', 1, 0, 1056, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994185, 'Cassandra\'s Strange Slush ', '', 'Give it to Cassandra before it disappears!', 1, '1.0', 1, 0, 1024, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994186, 'Mini Dragon Egg ', '', 'A Mini Dragon Egg that Cassandra has left in your care. You must hold it close and keep it warm for one hour for it to hatch. Logging out will cause it to be destroyed.', 1, '1.0', 1, 0, 672, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994187, 'Mini Dragon', '', 'A Mini Dragon that hatched from the egg Cassandra left with you. Return it to Cassandra to receive a reward!', 1, '1.0', 1, 0, 672, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
