	(3994192, 'Dark Feather', '', 'A black feather from a bird that has not been identified. Keep an eye on it for 15 minutes and it will transform into a Bright Feather.\\n#cIt will disappear once you log out.#', 1, '1.0', 1, 0, 1568, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994193, 'Bright Feather', '', 'A bright feather from a bird that has not been identified. Take it over to the Maple Admin.', 100, '1.0', 1, 0, 1536, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994195, '6 King Star', '', 'A large star specially made to commemorate MapleStory\'s 6th anniversary. Carry it with you for 45 minutes to receive a Star Stamp.', 100, '1.0', 1, 0, 1568, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994196, 'Hawkeye Sticker', '', 'A Hawkeye sticker. Collect all 5 Cygnus Knights stickers to receive a limited reward.', 100, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994197, 'Carta\'s Sandglass', '', 'It takes 2 hours for the sand in Carta\'s Sandglass to trickle down to the bottom.', 100, '1.0', 1, 0, 16, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
