	(3994856, 'Beating Treasure Map Piece', '', 'A piece of the treasure map that contains the location of a Heartstone.', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
	(3994869, 'Cold Winter Bean Sherbet', '', 'A bowl full of shaved ice topped with sweet, delicious bean paste. Beat the cold of winter with chilly ice and sweet beans!', 100, '1.0', 1, 0, 512, 0, 0, 0, 0, 0, '', '', 0, '', 0, '', 0, ''),
